static void xint_2c2e_0_0(double *buf, double omega, double lr_frac, double sr_frac, double alpha, double beta, double coe, double coe0,
                          double coe1, double coe2, double *AB, double x, double AB_dist2, double tmp)
{
    double scheme_0_0_0_0[1];
    double scheme_a[1] = {0};
    double scheme_b[1] = {0};
    double uu = 0.5 / alpha;
    double uu1 = 0.5 * coe / alpha;
    double uu2 = 0.5 / beta;
    double uu3 = 0.5 * coe1 / beta;
    double theta = 0.;
    if (omega != 0.)
        theta = omega / sqrt(omega * omega + x);
    cal_boys(0, x * AB_dist2, scheme_a);
    cal_boys(0, x * theta * theta * AB_dist2, scheme_b);
    for (int i = 0; i <= 0; i++)
        scheme_0_0_0_0[i] = tmp * (lr_frac * scheme_a[i] + sr_frac * scheme_b[i] * theta * pow(theta, 2 * i));
    buf[0] = scheme_0_0_0_0[0];
    return;
}

