static func_2c2e xint_2c2e_list[] = {
    xint_2c2e_0_0, NULL, NULL, NULL, NULL, NULL,
    xint_2c2e_1_0, xint_2c2e_1_1, NULL, NULL, NULL, NULL,
    xint_2c2e_2_0, xint_2c2e_2_1, xint_2c2e_2_2, NULL, NULL, NULL,
    xint_2c2e_3_0, xint_2c2e_3_1, xint_2c2e_3_2, xint_2c2e_3_3, NULL, NULL,
    xint_2c2e_4_0, xint_2c2e_4_1, xint_2c2e_4_2, xint_2c2e_4_3, xint_2c2e_4_4, NULL,
    xint_2c2e_5_0, xint_2c2e_5_1, xint_2c2e_5_2, xint_2c2e_5_3, xint_2c2e_5_4, xint_2c2e_5_5};
void xint_2c2e(Vector buf, int shla, int shlb, xint_info xint)
{
    const mol_info mol = xint->mol;
    const atm_info atm = xint->mol->atm;
    const bas_info aux = xint->aux;
    double *coea = get_bas_coe(shla, aux);
    double *coeb = get_bas_coe(shlb, aux);
    double *expa = get_bas_exp(shla, aux);
    double *expb = get_bas_exp(shlb, aux);
    int da = aux(NPRIM_VAL, shla);
    int db = aux(NPRIM_VAL, shlb);
    int la = aux(ANGULAR_VAL, shla);
    int lb = aux(ANGULAR_VAL, shlb);
    int len = (la + 1) * (lb + 1) * (la + 2) * (lb + 2) / 4;
    const Vector A = get_atm_coord(aux(ATOM_IND, shla), atm);
    const Vector B = get_atm_coord(aux(ATOM_IND, shlb), atm);
    double AB[3], coe, coe_, coe0, coe1, coe2, tmp, x;
    double AB_dist2;
    func_2c2e func = xint_2c2e_list[la * 6 + lb];
    AB[0] = A[0] - B[ 0];
    AB[1] = A[1] - B[ 1];
    AB[2] = A[2] - B[ 2];
    AB_dist2 = AB[0] * AB[0] + AB[1] * AB[1] + AB[2] * AB[2];
    memset(buf, 0, sizeof(double) * len);
    for (int i = 0; i < da; i++)
    {
        for (int j = 0; j < db; j++)
        {
            coe = expb[j] / (expa[i] + expb[j]);
            coe1 = expa[i] / (expa[i] + expb[j]);
            coe2 = 0.5 / (expa[i] + expb[j]);
            coe0 = 0.5 * coe / expa[i];
            tmp = 2.784163998415854 / sqrt(expa[i] + expb[j]) / (expa[i] * expb[j]);
            x = 2 * expa[i] * expb[j] * coe2;
            func(xint->cache, 0, 1, 0, expa[i], expb[j], coe, coe0, coe1, coe2, AB, x, AB_dist2, tmp); 
            for (int u = 0; u < len; u++)
                buf[u] += coea[i] * coeb[j] * xint->cache[u];
        }
    }
    return;
}

void cal_2c2e_matrix( Matrix e2_matrix, const bas_info aux, const mol_info mol)
{
    int msize = aux->msize;
    xint_info xint=init_xint(mol);
    load_xint_aux(aux, xint);
//    double buf[1024];
    double *buf=(double*)malloc(sizeof(double)*102400);

    int pi,pj;
    int di,dj;
    int ci,cj;
    int li,lj;
    for (int i=0; i<aux->nbas; i++)
    for (int j=0; j<=i; j++)
    {
        ci=xint_gtolen(aux(ANGULAR_VAL,i));
        cj=xint_gtolen(aux(ANGULAR_VAL,j));
        li=(aux(ANGULAR_VAL,i));
        lj=(aux(ANGULAR_VAL,j));
        pi=aux->shls_p[i];
        pj=aux->shls_p[j];
        // printf("%d %d:%d %d\n",i,j,li,lj);
        if (li>=lj)
        {
            xint_2c2e(buf,i,j,xint);
            for (int u=0, uu=0; u<ci; u++)
            for (int v=0; v<cj; v++, uu++)
            {
                e2_matrix[u+pi][v+pj]=buf[uu];
                e2_matrix[v+pj][u+pi]=buf[uu];
            }
        }
        else
        { 
            xint_2c2e(buf,j,i,xint);
            for (int u=0, uu=0; u<cj; u++)
            for (int v=0; v<ci; v++, uu++)
            {
                e2_matrix[u+pj][v+pi]=buf[uu];
                e2_matrix[v+pi][u+pj]=buf[uu];
            }
        }
    }

    free(buf);
    del_xint(xint);

    return;
}
